"joberr.ava1_exists": "ปลายทางมีอยู่แล้วบน PS5 เลือกเขียนทับเพื่อแทนที่ หรือเลือกปลายทางอื่น",
"joberr.ava1_commit_exists": "อัปโหลดไฟล์แล้วแต่เผยแพร่ไม่ได้เพราะปลายทางมีอยู่แล้ว เลือกเขียนทับเพื่อแทนที่ หรือเลือกปลายทางอื่น",
"joberr.ava1_cross_device": "ปลายทางอยู่คนละไดรฟ์กับพื้นที่พักไฟล์ PS5 จึงย้ายไฟล์ไม่ได้ เลือกปลายทางบนไดรฟ์เดียวกัน หรืออัปโหลดไปไดรฟ์ภายในก่อน",
"joberr.ava1_wrong_console": "อุปกรณ์ที่ที่อยู่นี้ไม่ใช่ PS5 ที่จับคู่กับแอปนี้ ตรวจสอบที่อยู่ หรือจับคู่กับคอนโซลนี้ใหม่",
"joberr.ava1_no_identity": "แอปนี้ยังไม่มีตัวตนสำหรับการจับคู่ จับคู่กับ PS5 จากหน้าจอการเชื่อมต่อ แล้วลองใหม่",
"joberr.zip_read_error": "อ่านไฟล์ .zip ไม่ได้ (ไฟล์หรือไดรฟ์อาจหายไประหว่างอ่าน) ตรวจสอบว่าต้นทางยังเชื่อมต่ออยู่ แล้วคลิกลองใหม่",
"joberr.ava1_zip_corrupt": "อ่านไฟล์ .zip นี้ไม่ได้: ไฟล์เสียหายหรือไม่สมบูรณ์ ดาวน์โหลดหรือสร้างใหม่ แล้วลองอีกครั้ง",
"joberr.ava1_7z_corrupt": "อ่านไฟล์ .7z นี้ไม่ได้: ไฟล์เสียหายหรือไม่สมบูรณ์ ดาวน์โหลดหรือสร้างใหม่ แล้วลองอีกครั้ง",
"joberr.ava1_7z_encrypted": "ไฟล์ .7z นี้เข้ารหัสไว้ จึงสตรีมไม่ได้ แตกไฟล์บนคอมพิวเตอร์ แล้วอัปโหลดโฟลเดอร์แทน",
"joberr.ava1_7z_unsafe_path": "ไฟล์ .7z นี้มีพาธไฟล์ที่ไม่ปลอดภัย (ออกนอกโฟลเดอร์ของตัวเอง) แตกไฟล์บนคอมพิวเตอร์ แล้วอัปโหลดโฟลเดอร์แทน",
"joberr.rar_password": "ไฟล์ .rar นี้ต้องใช้รหัสผ่าน หรือรหัสผ่านที่ให้มาไม่ถูกต้อง ใส่รหัสผ่านที่ถูกต้อง แล้วลองอีกครั้ง",
"joberr.rar_corrupt": "ไฟล์ .rar นี้เสียหาย หรือบางส่วนหายไปหรือเรียงผิดลำดับ ตรวจสอบว่ามีครบทุกส่วน แล้วลองอีกครั้ง",
"joberr.ava1_copy_lost": "PS5 ติดตามการคัดลอกนี้ไม่ได้ (ตัวช่วยรีสตาร์ตหรือการเชื่อมต่อหลุด) คลิกลองใหม่เพื่อเริ่มใหม่",
"joberr.ava1_copy_failed": "PS5 คัดลอกไม่เสร็จ ตรวจสอบพื้นที่ว่างและว่าต้นทางกับปลายทางยังใช้งานได้ แล้วลองอีกครั้ง",
"joberr.ava1_local_io": "คอมพิวเตอร์เครื่องนี้เขียนไฟล์ที่ดาวน์โหลดไม่ได้ ตรวจสอบสิทธิ์และพื้นที่ว่างของโฟลเดอร์ปลายทาง แล้วลองอีกครั้ง",
"joberr.ava1_bad_manifest": "PS5 ส่งรายการไฟล์ที่แอปนี้ไม่เข้าใจ อัปเดตตัวช่วยและแอปเป็นเวอร์ชันเดียวกัน แล้วลองอีกครั้ง",
"joberr.helper_not_ava1": "ตัวช่วยบน PS5 ไม่ทำงาน ส่งจากหน้าจอการเชื่อมต่อ (หรือใช้อัปเดตตัวช่วยหากแบนเนอร์เสนอ) แล้วลองอีกครั้ง",
"joberr.helper_not_ava1_web": "ตัวช่วยบน PS5 ไม่ทำงาน เว็บ UI นี้ส่งไม่ได้: เริ่ม payload ของ ps5upload บนคอนโซลด้วยตัวโหลด payload ที่คุณใช้ตามปกติ (หรือใช้อัปเดตตัวช่วยหากแบนเนอร์เสนอ) แล้วลองอีกครั้ง",
"joberr.not_paired": "PS5 เครื่องนี้ยังไม่ยอมรับแอปนี้ จับคู่ทั้งสอง (ปุ่มจับคู่…) แล้วลองอีกครั้ง",
"joberr.helper_starting": "ตัวช่วยบน PS5 ยังเริ่มทำงานอยู่ รอสักครู่ แล้วลองอีกครั้ง",
"joberr.ava1_failed": "ตัวช่วยบน PS5 เริ่มทำงานแล้ว แต่เซิร์ฟเวอร์ถ่ายโอนของมันไม่เริ่ม รีสตาร์ตคอนโซล แล้วลองอีกครั้ง",
"joberr.helper_not_running": "ไม่มีตัวช่วยทำงานอยู่บน PS5 ส่งตัวช่วยก่อน (หน้าจอการเชื่อมต่อของแอปเดสก์ท็อปหรือตัวโหลด payload ของคุณ) แล้วลองอีกครั้ง",
