"arcpkg.choose": "เลือกไฟล์บีบอัด…",
"arcpkg.help": "สำหรับ .zip, .7z หรือ .rar ที่มีไฟล์ .pkg หนึ่งไฟล์ขึ้นไปอยู่ในโฟลเดอร์ใดก็ได้ ระบบจะแตกเฉพาะแพ็กเกจไปยัง PS5 โดยตรง (ไม่มีการแตกไฟล์บนคอมพิวเตอร์เครื่องนี้) แล้วติดตั้งทีละรายการ: เกมหลักก่อน ตามด้วยอัปเดต แล้วจึงเป็น DLC รองรับ RAR หลายส่วน (.part1.rar, .part2.rar…): เลือกส่วนแรกและเก็บส่วนที่เหลือไว้ที่เดียวกัน ระบบจะถามรหัสผ่านเมื่อ RAR ต้องใช้ ส่วน ZIP และ 7z ที่มีรหัสผ่านไม่รองรับ",
