"install.stream.file.help": "เลือกไฟล์ .pkg หรือ .fpkg หรือลากมาวางที่ใดก็ได้ในหน้าต่างนี้ เปิดแอปไว้จนกว่าการติดตั้งจะเสร็จ ความคืบหน้าแสดงในคิวด้านบนและใน “งาน”",
