"install.tab.stream.lead": "PS5 ติดตั้งจากคอมพิวเตอร์เครื่องนี้หรือจากลิงก์โดยตรง ไม่มีการวางสำเนาไว้บน PS5 ก่อน จึงไม่ต้องใช้พื้นที่ว่างที่นั่น และเป็นวิธีติดตั้งที่เชื่อถือได้ที่สุด",
"install.tab.upload.lead": "คัดลอกแพ็กเกจไปยัง PS5 ก่อน แล้วติดตั้งจากสำเนานั้น ใช้เมื่อ PS5 เชื่อมต่อมายังคอมพิวเตอร์เครื่องนี้ไม่ได้ (การสตรีมล้มเหลวด้วยข้อผิดพลาดเครือข่าย) หรือเมื่อต้องการเก็บแพ็กเกจไว้บน PS5 เพื่อติดตั้งใหม่ภายหลังโดยไม่ต้องใช้คอมพิวเตอร์เครื่องนี้",
"install.upload.file.browser": "การคัดลอกแพ็กเกจไปยัง PS5 จากที่นี่ต้องใช้แอปเดสก์ท็อป ในเว็บ UI ให้ใช้ “สตรีมและติดตั้ง” หรือติดตั้งแพ็กเกจที่อยู่บน PS5 อยู่แล้วด้านล่าง",
"install.upload.file.help": "เลือกไฟล์ .pkg หรือ .fpkg สำเนาต้องใช้พื้นที่ว่างบน PS5 เท่ากับขนาดแพ็กเกจทั้งหมด และจะอยู่ในรายการด้านล่างจนกว่าคุณจะลบ",
"install.upload.file.title": "คัดลอกแพ็กเกจไปยัง PS5 แล้วติดตั้ง",
"linkcard.confirm.direct": "PS5 ดาวน์โหลดแพ็กเกจจากลิงก์เองแล้วติดตั้ง เมื่อเริ่มแล้วไม่ต้องใช้คอมพิวเตอร์เครื่องนี้อีก และความคืบหน้าแสดงบน PS5 (ดาวน์โหลด) ไม่ใช่ที่นี่ หาก PS5 เข้าถึงลิงก์ไม่ได้ แอปจะส่งต่อผ่านคอมพิวเตอร์เครื่องนี้แทน การติดตั้งทับเกมที่ติดตั้งอยู่แล้วอาจลบเกมนั้นหากตัวติดตั้งของ Sony ล้มเหลว ใช้เฉพาะลิงก์ของแพ็กเกจที่คุณเชื่อถือและมีสิทธิ์ติดตั้งเท่านั้น",
"linkcard.confirm.download": "คอมพิวเตอร์เครื่องนี้บันทึกแพ็กเกจทั้งหมดลงดิสก์ก่อน แล้วจึงติดตั้งไปยัง PS5 ต้องเปิดเครื่องไว้จนกว่าทั้งสองขั้นตอนจะเสร็จ และต้องมีพื้นที่ว่างสำหรับแพ็กเกจ การติดตั้งทับเกมที่ติดตั้งอยู่แล้วอาจลบเกมนั้นหากตัวติดตั้งของ Sony ล้มเหลว ใช้เฉพาะลิงก์ของแพ็กเกจที่คุณเชื่อถือและมีสิทธิ์ติดตั้งเท่านั้น",
