connection_payload_engine_unreachable: "แอปเชื่อมต่อกับเอนจินของตัวเองบนคอมพิวเตอร์เครื่องนี้ไม่ได้ จึงไม่รู้ว่าตัวช่วยเริ่มทำงานบน PS5 แล้วหรือยัง นี่ไม่ใช่ปัญหาของ PS5: ประกาศที่ด้านบนของหน้าต่างจะบอกสาเหตุและเริ่มเอนจินใหม่ได้ จากนั้นกด “ส่งตัวช่วย” อีกครั้ง ({error})",
"engine_problem.missing.fix": "กู้คืน ps5upload-engine จากที่กักกันของโปรแกรมป้องกันไวรัส (หรืออนุญาตให้ใช้) หรือติดตั้งแอปใหม่",
