"engine_problem.port.fix": "กด “เริ่มเอนจินใหม่” หากไม่ได้ผล ให้อนุญาต ps5upload-engine ในไฟร์วอลล์หรือโปรแกรมป้องกันไวรัส แล้วเริ่มแอปใหม่",
"engine_problem.port.why": "มีบางอย่างใช้ที่อยู่ของเอนจิน ({url}) อยู่แต่ไม่ตอบ: โปรแกรมอื่นบนพอร์ตนั้น หรือซอฟต์แวร์ความปลอดภัยที่บล็อกการเชื่อมต่อ",
"engine_problem.proxy.fix": "ปิดพร็อกซีหรือเครื่องมือ VPN สำหรับที่อยู่ภายในเครื่อง (127.0.0.1) หรือเปิดแอปโดยไม่มีการตั้งค่า http_proxy / ALL_PROXY",
"engine_problem.proxy.why": "คำขอที่ส่งถึงเอนจินถูกส่งไปยังพร็อกซีที่ตั้งไว้บนคอมพิวเตอร์เครื่องนี้แทน",
"engine_problem.remote.fix": "ตรวจสอบว่าเอนจิน (คอนเทนเนอร์ Docker หรือคอมพิวเตอร์อื่น) ทำงานอยู่และเข้าถึงได้ที่ที่อยู่นั้น หรือเปลี่ยนที่อยู่ใน “การตั้งค่า”",
"engine_problem.remote.why": "เอนจินที่แอปนี้ตั้งให้ใช้ ({url}) ไม่ตอบ",
"engine_problem.restart": "เริ่มเอนจินใหม่",
"engine_problem.slow.fix": "กด “เริ่มเอนจินใหม่” ไฟร์วอลล์หรือโปรแกรมป้องกันไวรัสที่กรองการเชื่อมต่อภายในเครื่องก็อาจเป็นสาเหตุได้: ให้อนุญาต ps5upload-engine",
"engine_problem.slow.why": "เอนจินทำงานอยู่แต่ไม่ตอบ",
"engine_problem.stopped.fix": "กด “เริ่มเอนจินใหม่” หากหยุดอีก หน้าจอ “บันทึก” จะแสดงสาเหตุ",
"engine_problem.stopped.why": "เอนจินไม่ได้ทำงาน: หยุดไปแล้ว หรือไม่เคยเริ่มทำงาน",
"engine_problem.title": "แอปเชื่อมต่อกับเอนจินบนคอมพิวเตอร์เครื่องนี้ไม่ได้",
"engine_problem.web.fix": "ตรวจสอบว่าเซิร์ฟเวอร์ (คอนเทนเนอร์ Docker) ทำงานอยู่ แล้วโหลดหน้านี้ใหม่",
"engine_problem.web.why": "หน้านี้ขาดการเชื่อมต่อกับเซิร์ฟเวอร์ ps5upload ที่ให้บริการหน้านี้",
gate_engine_down_body_v2: "หน้าจอนี้ต้องใช้เอนจินของแอป ซึ่งไม่ตอบ ประกาศที่ด้านบนของหน้าต่างจะบอกสาเหตุและเริ่มเอนจินใหม่ได้",
"profile.np.body": "ทำให้ PS5 ถือว่าบัญชีที่ลงชื่อเข้าใช้อยู่ได้ลงชื่อเข้าใช้ PlayStation Network แล้ว โดยไม่ติดต่อ Sony ฟีเจอร์บางอย่างของเครื่องเปิดให้เฉพาะบัญชีที่ลงชื่อเข้าใช้ รวมถึง Remote Play ใช้ np-fake-signin ของ earthonion ซึ่งดึงมาจากหน้าโปรเจกต์เมื่อคุณกดปุ่ม",
