"pkg.sony_80b21104": "PS5 ไม่รับแพ็กเกจนี้ (0x80B21104) ถ้าแพ็กเกจอื่นติดตั้งบนคอนโซลนี้ได้ ปัญหาอยู่ที่ไฟล์นี้: ส่วนใหญ่เป็นเกมใหม่ที่แพ็กเกจสร้างด้วยเครื่องมือใหม่กว่าที่เฟิร์มแวร์ของคอนโซลนี้เข้าใจ หรือแพ็กเกจที่ไม่ใช่บิลด์ลายเซ็นปลอม (FPKG) ให้ใช้แพ็กเกจที่ทำมาสำหรับเฟิร์มแวร์ของคุณ (backport) หรือติดตั้งเกมด้วยวิธีที่ไม่ผ่านตัวติดตั้ง: คัดลอกโฟลเดอร์เกม หรืออิมเมจเกม (.exfat หรือ .ffpfsc) สำหรับ ShadowMount+ ด้วยอัปโหลด",
