keep_ps5_awake_mode_hint_v2: "รีเซ็ตตัวจับเวลาสแตนด์บายอัตโนมัติของ PS5 เป็นระยะ เพื่อไม่ให้เข้าสู่โหมดพัก “ระหว่างอัปโหลดและติดตั้ง” ปกป้องการอัปโหลดที่ใช้เวลานาน (สาเหตุทั่วไปที่ทำให้อัปโหลดล้มเหลว ค่าเริ่มต้น) “เปิดตลอดขณะเชื่อมต่อ” ทำให้ทุกเครื่องที่มีตัวช่วยทำงานอยู่ไม่เข้าสู่โหมดพักตราบที่แอปเปิดอยู่ การสั่ง PS5 เข้าโหมดพักด้วยตัวเองยังทำได้ในทุกโหมด",
