processes_kill_payload_body: "การดำเนินการนี้จะหยุดเพย์โหลด \"{name}\" (kstuff, etaHEN และอื่นๆ) ทุกอย่างที่มันให้บริการจะหยุดจนกว่าคุณจะส่งอีกครั้ง และเกมที่ต้องใช้มันอาจเปิดไม่ได้",
