auto_bringup_hint: "เมื่อตัวโหลด (elfldr, พอร์ต 9021) ของ PS5 ที่บันทึกไว้ทำงานอยู่และตัวช่วยไม่ได้ทำงาน แอปจะเริ่มระบบอย่างรวดเร็วเอง: เพลย์ลิสต์เริ่มระบบของคุณถ้าตั้งไว้ จากนั้นตัวช่วย แล้วเพลย์ลิสต์ตัวโหลดอัตโนมัติของคุณ ทำครั้งเดียวทุกครั้งที่คอนโซลเปิดเครื่อง หลังโหมดพักจะส่งเฉพาะตัวช่วยอีกครั้ง แอปจะรอประมาณ 90 วินาทีหลังตัวโหลดปรากฏ เพื่อให้ตัวโหลดอัตโนมัติของคอนโซลทำงานเสร็จก่อน ปิดไว้เป็นค่าเริ่มต้น",
bringup_auto_hint_short: "ทำสิ่งนี้เองเมื่อตัวโหลดของ PS5 ทำงานแต่ตัวช่วยไม่ทำงาน ประมาณ 90 วินาทีหลังตัวโหลดปรากฏ ครั้งเดียวทุกครั้งที่คอนโซลเปิดเครื่อง",
