settings_card_system_files: "ไฟล์ระบบ",
settings_file_hint_v2: "ค่ากำหนดหลัก (ธีม ภาษา เอนจิน พาธเซฟ ค่าเริ่มต้นการอัปโหลด การช่วยการเข้าถึง แถบด้านข้าง) จะถูกสะท้อนไปยังไฟล์ JSON นี้ คุณแก้ไขเองได้ การแก้ไขจะมีผลเมื่อเปิดแอปครั้งถัดไป ไฟล์นี้ไม่ได้เก็บทุกอย่าง: ใช้ สำรอง / กู้คืน เพื่อย้ายค่ากำหนดทั้งหมด",
