upload_auto_resume_hint_browser: "หากการอัปโหลดขาดกลางคัน จะทำต่อจากจุดที่ค้างไว้เมื่อตัวช่วยของ PS5 ตอบกลับอีกครั้ง โดยลองใหม่หลายครั้งก่อนยอมแพ้ หน้านี้ส่งตัวช่วยใหม่เองไม่ได้: หาก PS5 รีสตาร์ท ให้ส่งตัวช่วยอีกครั้งก่อน ปัญหาร้ายแรงเช่น PS5 พื้นที่เต็ม ยังคงหยุดทันที เปิดเป็นค่าเริ่มต้น",
