upload_wake_for_uploads_hint: "เมื่อการอัปโหลดรอ PS5 ที่อยู่ในโหมดพัก จะส่งสัญญาณปลุกและทำต่อทันทีที่ตัวช่วยกลับมาทำงาน ใช้ได้เฉพาะเครื่องที่ตั้งค่าการปลุกไว้ในหน้าการเชื่อมต่อ เปิดไว้เป็นค่าเริ่มต้น",
