"netdoctor.hint.below_test": "การอัปโหลดนี้ทำงานที่ {speed} ต่ำกว่า {expected} ที่การทดสอบความเร็ววัดได้มาก",
"netdoctor.hint.runs_at": "การอัปโหลดนี้ทำงานที่ {speed}",
"netdoctor.hint.cause_source": "สิ่งที่ทำให้ช้าคือการอ่านไฟล์บนคอมพิวเตอร์เครื่องนี้ ไม่ใช่เครือข่าย: ไดรฟ์ USB หรือฮาร์ดดิสก์ โฟลเดอร์แชร์บนเครือข่าย (NAS) หรือการแตกไฟล์บีบอัด ช้ากว่าการเชื่อมต่อ การคัดลอกเกมลง SSD ภายในก่อน หรืออัปโหลดไฟล์ของไฟล์บีบอัดหลังแตกไฟล์แล้ว จะได้ความเร็วเต็มที่",
"netdoctor.hint.cause_disk": "สิ่งที่ทำให้ช้าคือไดรฟ์ของ PS5 ไม่ใช่เครือข่าย: ไดรฟ์ USB ภายนอก ไดรฟ์ที่ใกล้เต็ม หรือไฟล์เล็กหลายพันไฟล์ (แต่ละไฟล์ใช้เวลาของตัวเอง) เขียนช้ากว่าที่การเชื่อมต่อส่งมา อิมเมจเกม (.ffpkg หรือ .exfat) จะส่งเป็นไฟล์เดียว",
"netdoctor.hint.cause_workers": "PS5 ยังเขียนข้อมูลที่ได้รับอยู่ ไม่ได้รอเครือข่าย เมื่อมีไฟล์เล็กจำนวนมาก แต่ละไฟล์ใช้เวลาของตัวเอง อิมเมจเกม (.ffpkg หรือ .exfat) จะส่งเป็นไฟล์เดียว",
"netdoctor.hint.cause_cap": "สิ่งที่ทำให้ช้าคือขีดจำกัดความเร็วอัปโหลด (ประมาณ {cap} MiB/s ในหน้าจอนี้และในการตั้งค่า) ตั้งเป็น 0 เพื่อยกเลิก",
"profile.np.confirm_body_v2": "np-fake-signin จะเขียนไฟล์และการตั้งค่าการลงชื่อเข้าใช้ PlayStation Network สำหรับ {user} ลงใน PS5 ไม่มีการส่งข้อมูลใดไปยัง Sony จากนั้นให้เริ่ม PS5 ใหม่",
"profile.np.side_effect": "ผลข้างเคียงที่ทราบ: หลังจากนั้นคอนโซลบางเครื่องจะขอให้ \"ปิดการจำกัดคอนโซล PS5 ชั่วคราว\" ก่อนเปิดเกมใดๆ และ การตั้งค่า > ผู้ใช้และบัญชี > อื่นๆ > ออกจากระบบ อาจยังเป็นสีเทา แอปจะเก็บสำเนาของทุกสิ่งที่ np-fake-signin เปลี่ยนบน PS5 ไว้ก่อน ดังนั้น ยกเลิกการลงชื่อเข้าใช้ ที่นี่จะคืนค่าทั้งหมด",
"profile.np.backing_up": "กำลังเก็บสำเนาการตั้งค่าปัจจุบันของบัญชีไว้บน PS5…",
"profile.np.backup_failed": "PS5 เก็บสำเนาการตั้งค่าบัญชีไม่ได้ จึงไม่ได้เรียกใช้ np-fake-signin ให้แทนที่ตัวช่วยด้วยเวอร์ชันของแอปนี้แล้วลองอีกครั้ง ({error})",
"profile.np.step_restart_v2": "เริ่ม PS5 ใหม่ หากต้องการยกเลิกภายหลัง ให้กด ยกเลิกการลงชื่อเข้าใช้ ที่นี่แล้วเริ่มใหม่อีกครั้ง",
"profile.np.undo": "ยกเลิกการลงชื่อเข้าใช้",
"profile.np.undo_hint": "มีสำเนาการตั้งค่าของบัญชีนี้จากก่อนลงชื่อเข้าใช้เก็บไว้บน PS5 ปุ่มนี้จะคืนค่านั้น",
"profile.np.undo_confirm_title": "ยกเลิกการลงชื่อเข้าใช้หรือไม่",
"profile.np.undo_confirm_body": "คืนการตั้งค่าและไฟล์ของ {user} ให้เหมือนก่อนเรียกใช้ np-fake-signin จากนั้นให้เริ่ม PS5 ใหม่ ฟีเจอร์ที่ต้องใช้บัญชีที่ลงชื่อเข้าใช้ รวมถึง Remote Play อาจเปิดไม่ได้จนกว่าจะลงชื่อเข้าใช้อีกครั้ง",
