"rpg_user_title": "ลงชื่อเข้าใช้ผู้ใช้บน PS5",
"rpg_user_body": "เลือกผู้ใช้ที่จะใช้เล่นบนเครื่อง ไม่ต้องมีใครอยู่หน้าจอ แต่ผู้ใช้ต้องลงชื่อเข้าใช้อยู่ ใช้ผู้ใช้ที่ไม่มีรหัสผ่านเข้าสู่ระบบ เพราะรหัสผ่านจะหยุดการลงชื่อเข้าใช้อัตโนมัติเมื่อปลุกเครื่อง",
"rpg_account_title": "กำหนด ID บัญชีให้ผู้ใช้นั้น",
"rpg_account_body": "Remote Play จับคู่กับ ID บัญชี ผู้ใช้ที่เชื่อมกับ PlayStation Network มีอยู่แล้ว ส่วนผู้ใช้ออฟไลน์ต้องตั้งค่าใน «ผู้ใช้» ด้านบน (ใช้ ID ใดก็ได้ แต่ให้จดไว้ เพราะเซฟที่บันทึกหลังจากนั้นจะผูกกับ ID นี้)",
"rpg_signin_title": "ลงชื่อเข้าใช้บัญชีกับ PlayStation Network (ออฟไลน์)",
"rpg_signin_body": "PS5 ให้ใช้ Remote Play ได้เฉพาะบัญชีที่ลงชื่อเข้าใช้แล้ว หากการตั้งค่า Remote Play ของเครื่องเป็นสีเทา ให้เรียกใช้การลงชื่อเข้าใช้แบบออฟไลน์ด้านล่าง (ไม่มีการส่งข้อมูลใดไปยัง Sony) แล้วเริ่ม PS5 ใหม่ ยกเลิกภายหลังได้",
"rpg_signin_fix": "ไปที่การลงชื่อเข้าใช้",
"rpg_service_title": "เปิด Remote Play",
"rpg_service_body": "การตั้งค่า › ระบบ › Remote Play › เปิดใช้งาน Remote Play แอปเปิดให้คุณได้ และบนเฟิร์มแวร์ 10.00 ขึ้นไปยังอนุญาตให้ผู้ใช้รายนี้ได้ด้วย ถ้ากด เริ่ม แล้วขึ้นว่า Remote Play ปิดอยู่ ให้เปิดในการตั้งค่าของ PS5 เอง: สวิตช์บนเครื่องคือตัวที่มีผล",
"rpg_rest_title": "อนุญาตให้ปลุก PS5 จากโหมดพัก",
"rpg_rest_body": "การตั้งค่า › ระบบ › การประหยัดพลังงาน › คุณสมบัติที่ใช้ได้ในโหมดพัก: เปิด «เชื่อมต่ออินเทอร์เน็ตตลอดเวลา» และ «เปิดใช้งานการเปิด PS5 จากเครือข่าย» หากไม่เปิด เครื่องที่อยู่ในโหมดพักจะปลุกไม่ได้ และเครือข่ายจะหลับหลังผ่านไปไม่กี่วินาที ตัวเลือกเหล่านี้ดูได้บนเครื่องเท่านั้น",
"rpg_pair_title": "จับคู่แอปนี้กับเครื่อง",
"rpg_pair_body": "การเชื่อมต่อ › ปลุกและลงชื่อเข้าใช้ › ตั้งค่า คลิกเดียวจะลงทะเบียนแอปนี้กับ PS5 (เหมือนการจับคู่แอป PS Remote Play) และเก็บคีย์ไว้บนคอมพิวเตอร์นี้ การสตรีม การปลุก และการลงชื่อเข้าใช้ล้วนใช้คีย์เหล่านี้ ให้ทำใหม่หลังรีเซ็ตเครื่องหรือเปลี่ยนผู้ใช้",
"rpg_play_title": "เล่น",
"rpg_play_body": "เปิด «Remote Play» แล้วกด «เริ่ม» แอปจะปลุกเครื่องหากอยู่ในโหมดพัก ลงชื่อเข้าใช้ และสตรีม เล่นด้วยคอนโทรลเลอร์ที่ต่อกับคอมพิวเตอร์นี้ คีย์บอร์ด หรือการสัมผัส หากต้องการใช้แอป PS Remote Play ของ Sony หรือ chiaki-ng แทน ให้ขอ PIN ด้านล่างแล้วป้อนที่นั่น",
"rpg_play_fix": "เปิด Remote Play",
"rpg_title": "ตั้งค่า Remote Play",
