"rpg_t_start_a": "แอปนี้ยังไม่ได้จับคู่กับเครื่องนั้น: ทำขั้นตอนที่ 6 (การเชื่อมต่อ › ปลุกและลงชื่อเข้าใช้ › ตั้งค่า)",
"rpg_t_pair_q": "การตั้งค่าการจับคู่แจ้งว่าไม่มีผู้ใช้ที่ลงชื่อเข้าใช้พร้อมบัญชีที่เปิดใช้งานแล้ว",
"rpg_t_pair_a": "ขั้นตอนที่ 1 และ 2: ลงชื่อเข้าใช้ผู้ใช้บน PS5 และกำหนด ID บัญชีให้ แล้วลองอีกครั้ง",
"rpg_t_grey_q": "การตั้งค่า Remote Play ของ PS5 เป็นสีเทา",
"rpg_t_grey_a": "บัญชียังไม่ได้ลงชื่อเข้าใช้ PlayStation Network ให้เรียกใช้การลงชื่อเข้าใช้แบบออฟไลน์ (ขั้นตอนที่ 3) แล้วเริ่ม PS5 ใหม่",
"rpg_t_wake_q": "เครื่องไม่ตื่น หรือตื่นแล้วค้างอยู่ที่หน้าเลือกผู้ใช้",
"rpg_t_wake_a": "ตรวจสอบขั้นตอนที่ 5 บนเครื่อง ผู้ใช้ที่มีรหัสผ่านเข้าสู่ระบบจะหยุดการลงชื่อเข้าใช้อัตโนมัติ หากรีเซ็ตเครื่องหรือเปลี่ยนผู้ใช้ ให้ตั้งค่าการจับคู่ใหม่ (ขั้นตอนที่ 6)",
"rpg_t_black_q": "ภาพเป็นสีดำ กระตุก หรือเสียงแตก",
"rpg_t_black_a": "ใช้การเชื่อมต่อแบบมีสายหรือ Wi-Fi 5 GHz สำหรับ PS5 และคอมพิวเตอร์นี้ และลองตั้ง 720p หรือ 30 fps ในการตั้งค่าของ Remote Play ไฟร์วอลล์บนคอมพิวเตอร์นี้ต้องอนุญาตแอปในเครือข่ายท้องถิ่น (Remote Play ใช้พอร์ต TCP และ UDP 9295–9304) หากใช้เบราว์เซอร์ ให้ใช้ Chrome, Edge หรือ Safari รุ่นใหม่ เพราะภาพต้องใช้ WebCodecs",
"rpg_t_busy_q": "แจ้งว่า PS5 ยังปิดเซสชันก่อนหน้าไม่เสร็จ หรือมีเครื่องอื่นกำลังสตรีมอยู่",
"rpg_t_busy_a": "สตรีมได้ครั้งละหนึ่งเครื่อง และ PS5 ต้องใช้เวลาถึง 30 วินาทีหลังจบเซสชัน หยุดสตรีมอื่น รอสักครู่ แล้วกด «เริ่ม» อีกครั้ง",
"rpg_t_restrict_q": "หลังลงชื่อเข้าใช้แบบออฟไลน์ เกมขอให้ปิดการจำกัดคอนโซล",
"rpg_t_restrict_a": "ใช้ «ยกเลิกการลงชื่อเข้าใช้» ในหน้านี้แล้วเริ่มเครื่องใหม่ หรือยกเลิกการจำกัดใน การตั้งค่า › ครอบครัวและการควบคุมโดยผู้ปกครอง › การจำกัดคอนโซล PS5 (รหัสผ่าน 0000 หากยังไม่ได้เปลี่ยน)",
