"err_install_enoent_generic_v2": "ตัวติดตั้งของ Sony เปิดไฟล์ที่จำเป็นระหว่างติดตั้งไม่ได้ (ข้อผิดพลาดเคอร์เนล 0x80020002 = ENOENT) หากนี่เป็น pkg DLC แสดงว่ายังไม่ได้ติดตั้งเกมหลัก — ติดตั้งเกมหลักก่อน มิฉะนั้นแพ็กเกจที่เตรียมไว้อาจถูกลบระหว่างอัปโหลดกับติดตั้ง ลองติดตั้งใหม่อีกหนึ่งครั้ง หากยังล้มเหลว ให้ติดตั้งด้วย «สตรีมและติดตั้ง» ใน «อัปโหลดและติดตั้ง» ซึ่งส่งแพ็กเกจจากคอมพิวเตอร์เครื่องนี้โดยตรงแทนการคัดลอกไปยังเครื่องก่อน",
